import{_ as o}from"./chunks/2026-08-31-session-principal-continuity-alignment.BVrZM8pC.js";import{_ as i,C as a,o as r,c as s,a as t,E as c,a2 as d}from"./chunks/framework.Cm6XCzck.js";const w=JSON.parse('{"title":"The Conversation Continues, but the Account Has Changed","description":"","frontmatter":{"title":"The Conversation Continues, but the Account Has Changed","date":"2026-08-31","updated":"2026-08-31","column":"open-source-engineering","category":"daily","article_type":"comparative-engineering-analysis","edition":"research-center","research_question":"During cross-session recovery, why must conversation, precise-operation authority, execution principal, and evidence attribution each be verified independently?","summary":"Eleven approval-consumption controls and eight skill-session binding controls show that a session change alone need not invalidate an exact approval, while an old task cannot inherit authority unconditionally. Conversation continuity, operation authority, execution-principal continuity, and evidence attribution are four separate questions; real provider-account switching remains unverified in CodeFlowMu.","sources":"/en/research/evidence/2026-08-31-runtime-continuity","project_relevance":"substantive-relationship","item_id":"RCR-20260831-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-31-session-principal-continuity-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-08-31-session-principal-continuity.md","filePath":"en/engineering/2026-08-31-session-principal-continuity.md","lastUpdated":1788166937000}'),p={name:"en/engineering/2026-08-31-session-principal-continuity.md"};function h(l,e,u,g,m,v){const n=a("ArticleCover");return r(),s("div",null,[e[0]||(e[0]=t("p",null,[t("a",{href:"/joinwell52/zh/engineering/2026-08-31-session-principal-continuity"},"中文")],-1)),c(n,{image:"/assets/covers/daily-2026-08-31-session-principal-continuity-cover.png",kicker:"Runtime Continuity Research · 02",title:"The Conversation Continues, but the Account Has Changed",summary:"Conversation continuity does not prove continuity of approval, execution identity, or evidence ownership.",version:"RCR-20260831-02",status:"Comparative Engineering Research · 2026-08-31",languageHref:"/zh/engineering/2026-08-31-session-principal-continuity",languageLabel:"中文"}),e[1]||(e[1]=d('<h1 id="the-conversation-continues-but-the-account-has-changed" tabindex="-1">The Conversation Continues, but the Account Has Changed <a class="header-anchor" href="#the-conversation-continues-but-the-account-has-changed" aria-label="Permalink to &quot;The Conversation Continues, but the Account Has Changed&quot;">​</a></h1><p>Suppose an Agent receives human approval, is interrupted, and resumes in a new session. Can it continue the operation?</p><p>“A new session must always be approved again” turns routine recovery into an approval loop. “It is the same task, so it can naturally continue” is the opposite error: an unchanged task ID does not prove that the caller, target, or account is unchanged.</p><p>CodeFlowMu is the local multi-Agent collaboration system that we develop and maintain. It manages sessions, tool calls, human approval, and result records for role-bearing Agents working on engineering tasks. A task may span sessions, so we must separately ask what the new session may do, which provider or host principal now executes it, and where later evidence belongs.</p><p>The study separates four forms of continuity:</p><ul><li><strong>Conversation continuity</strong> — is this the same conversation or work context?</li><li><strong>Operation-authority continuity</strong> — does the original approval still cover this exact operation?</li><li><strong>Execution-principal continuity</strong> — which provider account, service principal, or host identity executes now?</li><li><strong>Evidence-attribution continuity</strong> — which session, task, thread, and agent own the invocation and its evidence?</li></ul><p>For developers and approvers, this prevents two bad defaults: extra approvals on ordinary recovery, and authority inherited merely because an old task exists. Our fixed-baseline experiments test eleven approval-consumption conditions and eight invocation-binding conditions. They support retaining existing safeguards and narrowing the untested provider-identity boundary; they do not support rewriting an entire session framework.</p><h2 id="_1-an-external-account-switch-case-is-a-real-scenario-not-our-proof" tabindex="-1">1. An external account-switch case is a real scenario, not our proof <a class="header-anchor" href="#_1-an-external-account-switch-case-is-a-real-scenario-not-our-proof" aria-label="Permalink to &quot;1. An external account-switch case is a real scenario, not our proof&quot;">​</a></h2><p><a href="https://www.ycombinator.com/companies/superset" target="_blank" rel="noreferrer">Superset</a> is a YC-backed open-source IDE for managing parallel coding Agents. Its <a href="https://github.com/superset-sh/superset/pull/6970" target="_blank" rel="noreferrer">PR #6970</a> lets a user switch the default provider account, restart eligible running agents, resume the same CLI session ID and conversation, and launch the new process under the new login. The PR reports manual QA with two real Claude accounts: the conversation survived while the new process received the new account environment.</p><p>That makes “same conversation, changed execution account” a real recovery scenario rather than a thought experiment. It does not decide whether a CodeFlowMu human approval covers a new principal; we did not perform a real two-account experiment in CodeFlowMu.</p><p><a href="https://github.com/openai/codex" target="_blank" rel="noreferrer">OpenAI Codex</a> offers a different, narrower contrast. One change preserves root/parent turn lineage across goal continuations and invalidates it when external context or the goal changes; another restores working directory only from a settings snapshot owned by the resumed thread, not a legacy or unowned snapshot. <a href="https://github.com/openai/codex/commit/4210c08defe92fe8828f789b6f9fda287ad3709e" target="_blank" rel="noreferrer">Lineage change</a>, <a href="https://github.com/openai/codex/commit/f5636bb733c4653a6b91413fed1aaf8842374f2e" target="_blank" rel="noreferrer">owned-snapshot change</a>.</p><p>Codex is handling ownership and recovery semantics, not human approval. The lesson used here is limited: historical state can be readable without being inheritable by the current execution.</p><h2 id="_2-a-session-change-alone-does-not-invalidate-an-old-approval" tabindex="-1">2. A session change alone does not invalidate an old approval <a class="header-anchor" href="#_2-a-session-change-alone-does-not-invalidate-an-old-approval" aria-label="Permalink to &quot;2. A session change alone does not invalidate an old approval&quot;">​</a></h2><p>The experiment fixes main commit <code>f0f42f01</code> and calls the real <code>OperationApprovalService</code>. Each independent case first receives ADMIN approval for a synthetic high-impact operation, then changes one consumption condition. It consumes authority but performs no remote action.</p><table tabindex="0"><thead><tr><th>Changed condition</th><th>Result</th><th>What it supports</th></tr></thead><tbody><tr><td>Original session consumes</td><td>accepted</td><td>normal path works</td></tr><tr><td>session-1 → session-2, all other bindings and action match</td><td>accepted; receipt records session-2</td><td>ordinary recovery may use matching approval</td></tr><tr><td>project, agent, task, thread, or role mismatch</td><td>not accepted</td><td>each ownership boundary is checked</td></tr><tr><td>operation fingerprint, target, or request snapshot changes</td><td>not accepted</td><td>exact operation identity is checked</td></tr><tr><td>empty session</td><td>not accepted</td><td>this consumption path requires a session identifier</td></tr></tbody></table><p>Both accepted paths reject a second consumption as <code>APPROVAL_ALREADY_CONSUMED</code>. The nine other conditions did not obtain authority; that is not nine execution failures.</p><p>The reason the resumed-session row is not a vulnerability is precise: the operation digest intentionally does not make a session string immutable. Consumption instead checks project, fingerprint, agent, task, thread, and role, requires non-empty old and current session identifiers, and stores the consuming session in the receipt. <strong>Approval binds a constrained operation identity, not one transient process session.</strong></p><p>The method receives context supplied by the caller chain; it does not consult <code>SessionStore</code> at this point. The result proves which fields participate in matching, not that every external entry point can supply them honestly.</p><p><img src="'+o+'" alt="Two aligned cobalt interlocking collars share one crystal core and violet provenance filament; an amber collar is offset."></p><p><em>Figure 1. Recovery is allowed by a set of matching conditions, not by an unchanged session string. The offset collar means the current condition does not match; it does not mean every new session requires reapproval. Source: RCR-20260831 de-identified E-B1 authorization matrix.</em></p><h2 id="_3-permission-to-proceed-and-proof-of-ownership-are-different-evidence" tabindex="-1">3. Permission to proceed and proof of ownership are different evidence <a class="header-anchor" href="#_3-permission-to-proceed-and-proof-of-ownership-are-different-evidence" aria-label="Permalink to &quot;3. Permission to proceed and proof of ownership are different evidence&quot;">​</a></h2><p>Authority consumption does not prove which session owns a later skill invocation. We separately test the V2.1.2 skill-binding path. The fixture registers two sessions in <code>SessionStore</code>, bound to one synthetic task and thread, and writes invocation records through the actual journal service.</p><table tabindex="0"><thead><tr><th>Input case</th><th>Persisted binding</th><th>Reason</th></tr></thead><tbody><tr><td>Registered original or resumed session with matching ownership</td><td><code>verified</code></td><td>task, thread, and session are recorded</td></tr><tr><td>Unregistered or agent/task/thread-mismatched session</td><td><code>invalid_claim</code></td><td>the declared identity is rejected as binding evidence</td></tr><tr><td>Legitimate system action without a session and with a reason</td><td><code>not_applicable</code></td><td><code>session_id:null</code> plus reason is retained</td></tr><tr><td>No session and no reason</td><td><code>invalid_claim</code></td><td>not disguised as legitimate sessionless work</td></tr></tbody></table><p>All eight captured records pass their product integrity checks; changing a task field causes rejection. That detects alteration in this fixture. It does not prove that an intact record is semantically correct, that a skill recommendation is correct, or that a task is complete.</p><p>Only two records are <code>verified</code>; five are <code>invalid_claim</code>; one is <code>not_applicable</code>. Six <code>session_id:null</code> values are therefore not a missing-field rate: five preserve the refusal to treat an untrusted claim as a bound session and one documents a legitimate sessionless system action. <strong>Attribution answers who a record belongs to, not who was authorized to execute an operation.</strong></p><h2 id="_4-execution-principal-is-not-yet-a-verified-authority-contract-input" tabindex="-1">4. Execution principal is not yet a verified authority-contract input <a class="header-anchor" href="#_4-execution-principal-is-not-yet-a-verified-authority-contract-input" aria-label="Permalink to &quot;4. Execution principal is not yet a verified authority-contract input&quot;">​</a></h2><p>CodeFlowMu&#39;s execution contract has fields for provider, host slot, workspace, tools, and governance authority. A field existing, a comparison function noticing a field, and an entry point enforcing a consequence are three different levels of fact.</p><p>P4 placed a synthetic <code>PROVIDER_ACCOUNT_ID</code> in an MCP environment and changed it. The contract digest did not change and comparison found no conflict; changing workspace did. This does not prove that a real provider-account switch bypasses permission. It does establish a narrower point: <strong>a provider-account string appearing in an environment does not automatically become a governance identity.</strong> <a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/fixtures/historical-probes.json">P4 capture</a></p><p>The needed chain is <code>identity source → authenticated principal → authority contract → execution receipt</code>. A client sending an account ID does not answer who is entitled to assert that identity. We have not yet demonstrated that chain for provider switching.</p><h2 id="_5-what-a-real-next-experiment-would-test" tabindex="-1">5. What a real next experiment would test <a class="header-anchor" href="#_5-what-a-real-next-experiment-would-test" aria-label="Permalink to &quot;5. What a real next experiment would test&quot;">​</a></h2><p>Under authorized isolated test accounts, the next study would compare: normal recovery on the same account and target; the same conversation after a provider-account switch; and explicit rework or a changed target. It would verify the trusted source of the principal, the approved operation snapshot, the grant scope, and the attribution of the resulting session. Until then, retain the verified precise-operation approval and skill binding safeguards, and do not claim that account switching is safe or unsafe.</p><p>The <a href="/joinwell52/en/research/evidence/2026-08-31-runtime-continuity">bilingual evidence guide</a> provides the eleven and eight captured cases plus the checker. The public check does not contain signing keys and does not pretend to rerun product HMAC verification.</p><p><strong>Conversation continuity, operation-authority continuity, execution-principal continuity, and evidence-attribution continuity are four different questions. Proof of any one does not prove the other three.</strong></p>',33))])}const b=i(p,[["render",h]]);export{w as __pageData,b as default};
